/* static/css/style.css */
/* Purpose: Define styles for the frontend of the Note-Taking Application */

body {
    font-family: Arial, sans-serif;
    background-color: #f9f9f9;
    margin: 0;
    padding: 0;
    color: #333;
}

header {
    background-color: #4CAF50;
    color: white;
    padding: 20px;
    text-align: center;
    font-size: 24px;
    font-weight: bold;
}

main {
    margin: 20px auto;
    max-width: 800px;
    background-color: #fff;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    border-radius: 8px;
    overflow: hidden;
}

.container {
    padding: 20px;
}

button {
    background-color: #4CAF50;
    color: white;
    border: none;
    padding: 10px 15px;
    cursor: pointer;
    border-radius: 5px;
    font-size: 16px;
}

button:hover {
    background-color: #45a049;
}

input[type="text"],
textarea {
    width: 100%;
    padding: 10px;
    margin: 10px 0;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 16px;
}

textarea {
    resize: vertical;
    min-height: 100px;
}

.note {
    background-color: #f1f1f1;
    padding: 15px;
    margin: 15px 0;
    border-left: 4px solid #4CAF50;
    border-radius: 4px;
}

.note h2 {
    margin: 0 0 10px 0;
    font-size: 20px;
    color: #4CAF50;
}

.note p {
    margin: 0;
    font-size: 16px;
}

footer {
    text-align: center;
    padding: 10px;
    background-color: #4CAF50;
    color: white;
    font-size: 14px;
    position: fixed;
    bottom: 0;
    width: 100%;
}

document.addEventListener("DOMContentLoaded", function () {
    // Functions to handle notes operations
    const createNoteButton = document.getElementById("create-note-btn");
    const searchInput = document.getElementById("search-input");
    const notesContainer = document.getElementById("notes-container");

    // Fetch notes from the server and display them
    async function fetchNotes() {
        try {
            const response = await fetch("/api/notes");
            const notes = await response.json();
            renderNotes(notes);
        } catch (error) {
            console.error("Error fetching notes:", error);
        }
    }

    // Render notes in the container
    function renderNotes(notes) {
        notesContainer.innerHTML = ""; // Clear existing notes
        if (notes.length === 0) {
            notesContainer.innerHTML = "<p>No notes found</p>";
            return;
        }
        notes.forEach((note) => {
            const noteElement = document.createElement("div");
            noteElement.className = "note";
            noteElement.innerHTML = `
                <h3>${note.title}</h3>
                <p>${note.content}</p>
                <button class="delete-note-btn" data-id="${note.id}">Delete</button>
            `;
            notesContainer.appendChild(noteElement);
        });
    }

    // Create a new note
    async function createNote() {
        const title = prompt("Enter note title:");
        const content = prompt("Enter note content:");
        if (!title || !content) {
            alert("Both title and content are required!");
            return;
        }
        try {
            const response = await fetch("/api/notes", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                },
                body: JSON.stringify({ title, content }),
            });
            if (response.ok) {
                fetchNotes();
            } else {
                console.error("Error creating note:", await response.text());
            }
        } catch (error) {
            console.error("Error creating note:", error);
        }
    }

    // Delete a note
    async function deleteNote(noteId) {
        try {
            const response = await fetch(`/api/notes/${noteId}`, {
                method: "DELETE",
            });
            if (response.ok) {
                fetchNotes();
            } else {
                console.error("Error deleting note:", await response.text());
            }
        } catch (error) {
            console.error("Error deleting note:", error);
        }
    }

    // Search notes
    function searchNotes(query) {
        const allNotes = Array.from(notesContainer.querySelectorAll(".note"));
        allNotes.forEach((note) => {
            const title = note.querySelector("h3").textContent.toLowerCase();
            const content = note.querySelector("p").textContent.toLowerCase();
            if (title.includes(query) || content.includes(query)) {
                note.style.display = "block";
            } else {
                note.style.display = "none";
            }
        });
    }

    // Event listeners
    createNoteButton.addEventListener("click", createNote);
    searchInput.addEventListener("input", (e) => {
        const query = e.target.value.toLowerCase();
        searchNotes(query);
    });
    notesContainer.addEventListener("click", (e) => {
        if (e.target.classList.contains("delete-note-btn")) {
            const noteId = e.target.getAttribute("data-id");
            deleteNote(noteId);
        }
    });

    // Initial fetch of notes
    fetchNotes();
});

from app.database import db
from werkzeug.security import generate_password_hash, check_password_hash


class User(db.Model):
    __tablename__ = 'users'

    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password_hash = db.Column(db.String(128), nullable=False)

    def __init__(self, username, email, password):
        self.username = username
        self.email = email
        self.set_password(password)

    def set_password(self, password):
        """Hash and store the password."""
        self.password_hash = generate_password_hash(password)

    def check_password(self, password):
        """Verify the password against the hash."""
        return check_password_hash(self.password_hash, password)

    def to_dict(self):
        """Return a dictionary representation of the user."""
        return {
            'id': self.id,
            'username': self.username,
            'email': self.email
        }

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.database import db
from app.models.problem import Problem

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def list_problems():
    try:
        problems = Problem.query.all()
        return render_template('problem.html', problems=[problem.to_dict() for problem in problems])
    except Exception as e:
        flash(f"Error loading problems: {str(e)}", "error")
        return render_template('problem.html', problems=[])

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def view_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            flash("Problem not found!", "error")
            return redirect(url_for('problem.list_problems'))
        return render_template('problem.html', problem=problem.to_dict())
    except Exception as e:
        flash(f"Error loading problem: {str(e)}", "error")
        return redirect(url_for('problem.list_problems'))

@problem_bp.route('/problems/new', methods=['GET', 'POST'])
def create_problem():
    if request.method == 'POST':
        try:
            title = request.form.get('title')
            description = request.form.get('description')
            if not title or not description:
                flash("Title and description are required!", "error")
                return redirect(url_for('problem.create_problem'))

            new_problem = Problem(title=title, description=description)
            db.session.add(new_problem)
            db.session.commit()
            flash("Problem created successfully!", "success")
            return redirect(url_for('problem.list_problems'))
        except Exception as e:
            flash(f"Error creating problem: {str(e)}", "error")
            return redirect(url_for('problem.create_problem'))

    return render_template('submit.html')

@problem_bp.route('/problems/<int:problem_id>/edit', methods=['GET', 'POST'])
def edit_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            flash("Problem not found!", "error")
            return redirect(url_for('problem.list_problems'))

        if request.method == 'POST':
            title = request.form.get('title')
            description = request.form.get('description')
            if not title or not description:
                flash("Title and description are required!", "error")
                return redirect(url_for('problem.edit_problem', problem_id=problem_id))

            problem.title = title
            problem.description = description
            db.session.commit()
            flash("Problem updated successfully!", "success")
            return redirect(url_for('problem.view_problem', problem_id=problem_id))

        return render_template('submit.html', problem=problem.to_dict())
    except Exception as e:
        flash(f"Error editing problem: {str(e)}", "error")
        return redirect(url_for('problem.list_problems'))

@problem_bp.route('/problems/<int:problem_id>/delete', methods=['POST'])
def delete_problem(problem_id):
    try:
        problem = Problem.query.get(problem_id)
        if not problem:
            flash("Problem not found!", "error")
            return redirect(url_for('problem.list_problems'))

        db.session.delete(problem)
        db.session.commit()
        flash("Problem deleted successfully!", "success")
        return redirect(url_for('problem.list_problems'))
    except Exception as e:
        flash(f"Error deleting problem: {str(e)}", "error")
        return redirect(url_for('problem.list_problems'))

from flask import Blueprint, request, jsonify, render_template
from app.database import db
from app.models.user import User

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def list_users():
    try:
        users = User.query.all()
        user_list = [user.to_dict() for user in users]
        return jsonify(user_list), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def view_user(user_id):
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        return jsonify(user.to_dict()), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users', methods=['POST'])
def create_user():
    try:
        data = request.json
        if not data or 'username' not in data or 'password' not in data:
            return jsonify({'error': 'Invalid input'}), 400

        new_user = User(username=data['username'])
        new_user.set_password(data['password'])

        db.session.add(new_user)
        db.session.commit()

        return jsonify(new_user.to_dict()), 201
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        data = request.json
        if not data:
            return jsonify({'error': 'Invalid input'}), 400

        if 'username' in data:
            user.username = data['username']
        if 'password' in data:
            user.set_password(data['password'])

        db.session.commit()

        return jsonify(user.to_dict()), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404

        db.session.delete(user)
        db.session.commit()

        return jsonify({'message': 'User deleted successfully'}), 200
    except Exception as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

from flask import Blueprint, request, jsonify, render_template, redirect, url_for
from app.database import db
from app.models.solution import Solution
from app.models.problem import Problem

solution_bp = Blueprint('solution', __name__)

@solution_bp.route('/solutions', methods=['GET'])
def list_solutions():
    """Retrieve and list all solutions."""
    solutions = Solution.query.all()
    return jsonify([solution.to_dict() for solution in solutions])

@solution_bp.route('/solutions/<int:solution_id>', methods=['GET'])
def view_solution(solution_id):
    """View a specific solution."""
    solution = Solution.query.get(solution_id)
    if not solution:
        return jsonify({'error': 'Solution not found'}), 404
    return jsonify(solution.to_dict())

@solution_bp.route('/solutions/new', methods=['GET', 'POST'])
def create_solution():
    """Create a new solution."""
    if request.method == 'GET':
        problems = Problem.query.all()
        return render_template('submit.html', problems=problems)

    if request.method == 'POST':
        data = request.form
        problem_id = data.get('problem_id')
        content = data.get('content')

        if not problem_id or not content:
            return jsonify({'error': 'Problem ID and content are required'}), 400

        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Invalid problem ID'}), 404

        solution = Solution(problem_id=problem_id, content=content)
        db.session.add(solution)
        db.session.commit()
        return redirect(url_for('solution.list_solutions'))

@solution_bp.route('/solutions/<int:solution_id>/edit', methods=['GET', 'POST'])
def edit_solution(solution_id):
    """Edit an existing solution."""
    solution = Solution.query.get(solution_id)
    if not solution:
        return jsonify({'error': 'Solution not found'}), 404

    if request.method == 'GET':
        problems = Problem.query.all()
        return render_template('submit.html', solution=solution, problems=problems)

    if request.method == 'POST':
        data = request.form
        solution.content = data.get('content', solution.content)
        solution.problem_id = data.get('problem_id', solution.problem_id)

        db.session.commit()
        return redirect(url_for('solution.list_solutions'))

@solution_bp.route('/solutions/<int:solution_id>/delete', methods=['POST'])
def delete_solution(solution_id):
    """Delete a solution."""
    solution = Solution.query.get(solution_id)
    if not solution:
        return jsonify({'error': 'Solution not found'}), 404

    db.session.delete(solution)
    db.session.commit()
    return redirect(url_for('solution.list_solutions'))
